def min_recolors_to_nice_garland(n, s):
    dp = [[float('inf')] * 3 for _ in range(n)]
    dp[0][ord(s[0]) - ord('R')] = 0

    for i in range(1, n):
        for j in range(3):
            if (j + i) % 3 == 0:
                dp[i][(j + 1) % 3] = min(dp[i][(j + 1) % 3], dp[i - 1][j])
                dp[i][(j + 2) % 3] = min(dp[i][(j + 2) % 3], dp[i - 1][j])
            else:
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + 1)

    min_recolors = min(dp[n - 1])
    result = [''] * n

    def backtrack(i, prev_color):
        if i < 0:
            return
        if dp[i][prev_color] == dp[i - 1][prev_color]:
            result[i] = chr(prev_color + ord('R'))
            backtrack(i - 1, prev_color)
        else:
            for j in range(3):
                if dp[i][prev_color] == dp[i - 1][j] + 1:
                    result[i] = chr(j + ord('R'))
                    backtrack(i - 1, j)
                    break

    backtrack(n - 1, dp[n - 1].index(min_recolors))

    return min_recolors, ''.join(result)

